import os, json, glob, re

def load_all_grids():
    """Load all grids from the Messages tool history"""
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    sessions_path = os.path.join(d, '../../sessions')
    basename = os.path.basename(d)
    jsonl_path = os.path.join(sessions_path, basename + '.jsonl')

    try:
        content = open(jsonl_path).read()
    except FileNotFoundError:
        print(f"Sessions file not found at {jsonl_path}")
        return {}

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = []
        remaining = content[m.end():].split('\n')
        for i in range(h):
            rows.append(remaining[i] if i < len(remaining) else '')

        if k not in G and h > 0 and len(rows) > 0 and rows[0].strip():
            if not all(x.isdigit() for row in rows for x in row.split()):
                continue
            grid = [[int(x) for x in r.strip().split()] for r in rows if r.strip()]
            G[k] = grid

    return G

# Load and display demos
G = load_all_grids()
print("Keys found (including 'Test input'):", sorted(G.keys()))
for k in sorted(G.keys()):
    g = G[k]
    if g and isinstance(g, list):
        w = len(g[0]) if g else 0
        print(f"\n--- {k} ({len(g)}x{w}) ---")
        print(g[:5] if len(g) > 5 else g)
        print(f"Total: {len(g)} rows x {w} cols")

